For fixed $\kappa >0$, what is the typical distribution of the capacity?  In particular, 
    \begin{itemize}
        \item What is the satisfiability threshold, i.e., the largest value of $\alpha$ such that $ \mathbf{X}_{n,\alpha n,\kappa}$ is non-empty whp? 
        \item How sharp is the satisfiability transition? More pecisely, we ask for the width of the scaling window: how much must $m$ increase for the probability of satisfiability to decrease from $1-\epsilon$ to $\epsilon$? On what scale does the capacity typically fluctuate?
    \end{itemize}

\label{def:DG}
    For $r > 1$, let $\mu_{r}$ denote the ``punctured'' discrete Gaussian supported on $\mathbb{Z} \setminus \{0\}$ having mean zero and variance $r^2$. For a uniquely determined $\sigma := \sigma(r)$ and $Z:=Z(r)$, its probability mass function is
    \begin{equation}
        \mu_{r}(x) := \frac{1}{Z}\exp\left(-\frac{x^2}{2\sigma^2}\right),
        \qquad x \in \mathbb{Z} \setminus \{0\}.
    \end{equation}
    Equivalently, $\mu_r$ is the unique maximum-entropy distribution on
    $\mathbb{Z}\setminus\{0\}$ with mean zero and variance $r^2$. We also set
    $\mu_1$ as the uniform distribution on $\{-1,1\}$.

The \textit{annealed free energy} function is given by
\begin{equation}\label{eq:F1-def}
    F_1(\kappa,\alpha,r):=H(\mu_r)+\alpha\log p(\kappa/r).
\end{equation}
The \textit{first-moment prediction for the satisfiability threshold} is
\begin{equation}\label{eq:capacity definition}
        \alpha_c(\kappa)
        :=\sup_{r\ge1}\frac{H(\mu_r)}{-\log p(\kappa/r)}.
    \end{equation}
Given $\kappa > 0$ and $\alpha > 1$, the \emph{maximizing radius} is $$r_*(\kappa,\alpha)=\arg\max_{r\ge1}F_1(\kappa,\alpha,r).$$

\label{hyp:maxima}
Fix $\kappa>0$ and $\alpha\in(1,\alpha_c(\kappa)]$, and let
$r_*=r_*(\kappa,\alpha)$. Then
\begin{enumerate}
    \item
    \begin{equation}\label{eq:F2-maxima}
        F_2(\kappa,\alpha,r_*,\theta)
        <F_2(\kappa,\alpha,r_*,0)
        \qquad
        \text{for every }\theta\in(-1,1)\setminus\{0\};
    \end{equation}
    \item
    \[
        \partial_{\theta\theta}^2 F_2(\kappa,\alpha,r_*,0) < 0
    \]
\end{enumerate}

\label{thm:unique-max}
If $\kappa\ge10$, then
$\alpha_c(\kappa)>1+\kappa^{-2}$ and \cref{hyp:maxima} holds whenever
\begin{equation}\label{eq:profile-main-range}
    1+\frac1{\kappa^2}\le\alpha\le\alpha_c(\kappa).
\end{equation}

\label{thm:main}
Fix $\kappa>0$ such that $\alpha_c(\kappa)>1$ and
\cref{hyp:maxima} holds for $\alpha=\alpha_c(\kappa)$. 
There exists a function $f_\kappa: \mathbb R \to [0,1]$ with $\lim_{t\to-\infty}f_\kappa(t)=0$ and
$\lim_{t\to+\infty}f_\kappa(t)=1$ so that the following holds.  For each fixed $T > 0$, uniformly for $t \in  [-T,T]$, when 
$m=\alpha_cn+t\in\mathbb N$,
\begin{equation}\label{eq:main-intro-scaling-limit}
    \mathbb{P}_{}\left[ \mathbf{X}_{n,m,\kappa} = \emptyset \right] = f_\kappa(t)+o_n(1)
\end{equation}
In particular, $\alpha_c$ is the sharp satisfiability threshold, and the scaling window is of constant order.

\label{q}
    Fix $\kappa>0$.
    \begin{enumerate}
        \item Does strong freezing hold for all $\alpha$ below the satisfiability threshold?
        \item Is $\alpha_c(\kappa)$ the satisfiability threshold for all $\kappa$? 
    \end{enumerate}

\label{prop:dg2}
    Let $r,\hat{r} > 1$ and $\theta \in (-1,1)$ satisfy
    \begin{equation}\label{eq:dg2-condition}
        r\hat{r}|\theta| < 1 + \sqrt{(r^2-1)(\hat{r}^2-1)}\,.
    \end{equation}
    Then $\mu_{r,\hat r,\theta}^{(2)}$ exists and there is also a unique tuple of parameters $(a,b,c)$ and a normalizing constant $\Psi$ with
    \[
        \mu_{r,\hat r,\theta}^{(2)}(x,y) =\exp\{ax^2+bxy+cy^2-\Psi(a,b,c)\}.
    \]

\label{prop:2d-lattice-count}
For every feasible $(r,\hat r,\theta)$ with $r,\hat r>1$ and $\theta\in(-1,1)$,
\begin{align*}
    N(r,\hat r,\theta)
    &=e^{nH(\mu_{r,\hat r,\theta}^{(2)})}\,
      \mathbb{P}_{(X_i,Y_i)\stackrel{\mathrm{iid}}\sim\mu_{r,\hat r,\theta}^{(2)}}\left[\sum_{i=1}^n(X_i^2,X_iY_i,Y_i^2)
       =(nr^2,n\theta r\hat r,n\hat r^2)\right]\le e^{nH(\mu_{r,\hat r,\theta}^{(2)})}.
\end{align*}
Fix $\delta,\epsilon>0$ and $C<\infty$. There exists $\eta>0$
such that, uniformly over feasible triples satisfying
\[
    r,\hat r\in[1+\delta,C],\qquad
    |r-\hat r|\le\eta,\qquad
    |\theta|\le1-\epsilon,
\]
one has
\begin{equation}\label{eq:2d lattice count}
    N(r,\hat r,\theta)
    =e^{nH(\mu_{r,\hat r,\theta}^{(2)})}
      \frac{1+o(1)}{(2\pi n)^{3/2}\sqrt{\det\Gamma_{r,\hat r,\theta}}}
    =e^{nH(\mu_{r,\hat r,\theta}^{(2)})+O(\log n)},
\end{equation}
and also
\begin{equation}\label{eq:N2 expansion}
    \frac1n\log N(r,\hat r,\theta)
    =\frac1n\log\frac{N(r)N(\hat r)}{\sqrt{2\pi n r^2\hat r^2}}
      +\frac{\theta^2}{2}
       \left(\partial_{\theta\theta}^2H(\mu_{r,\hat r,0}^{(2)})+O(n^{-1})\right)
      +O(\theta^4)+o(n^{-1}).
\end{equation}

\label{lemma:F1 shape}
Fix $\kappa>0$ and $\alpha>1$, and set
\[
    f(v):=F_1(\kappa,\alpha,\sqrt v),
    \qquad v>1.
\]
For every $v>1$, at least one of the following holds:
\begin{enumerate}
    \item $f''(v)<0$;
    \item $f'(v)<0$.
\end{enumerate}
Moreover, $f'(v)>0$ for $v$ sufficiently close to $1$, while
$f'(v)<0$ for all sufficiently large $v$.

\label{prop:F2 entropy derivatives}
Fix $r,\hat r>1$ and restrict $\theta\in(-1,1)$
to the domain \eqref{eq:dg2-condition}. Then
\begin{equation}\label{eq:H-prime}
    \partial_\theta H(\mu^{(2)}_{r,\hat r,\theta})
    =-br\hat r.
\end{equation}
Moreover, 
\begin{equation}\label{eq:H''}
    \left.
    \partial_{\theta\theta}^2
    H(\mu^{(2)}_{r,\hat r,\theta})
    \right|_{\theta=0}=-1,
\end{equation}
and $H(\mu_{r,\hat{r},\theta}^{(2)})$ is strictly concave in $\theta$ on its domain.

\label{prop:F2'' central}
For every $\kappa>0$, $\alpha>0$, and $r,\hat r>1$,
\begin{equation}\label{eq:F2-center}
    \left.\partial_{\theta\theta}^2
      F_2(\kappa,\alpha,r,\hat r,\theta)\right|_{\theta=0}
    =-1+4B_{\kappa/r,\alpha}B_{\kappa/\hat r,\alpha}.
\end{equation}

\label{lem:Gaussian-overlap-estimates}
For $K>0$ and $0<\theta<1$,
\begin{align}
    G_K(\theta)
       &\le\frac{1-p(K)}{p(K)}\,\theta^2,
       \label{eq:Gaussian-Hermite-coarse}\\
    G_K(\theta)
       &\le\frac{d(K)^2}{2}\theta^2
       +\left(\frac{1-p(K)}{p(K)}
                    -\frac{d(K)^2}{2}\right)\theta^4.
       \label{eq:Gaussian-Hermite-refined}
\end{align}
Moreover, if $K\le2$, then
\begin{equation}\label{eq:Gaussian-small-window}
    G_K(\theta)
       \le-\frac{d(K)^2}{2}\log(1-\theta^2).
\end{equation}

\label{lem:entropy-interpolation}
If $r\ge1.2$ and $0\le\theta\le1$, let $Z_r:=Z(r)$ denote the
normalizing constant in \cref{def:DG}, and set $c_r:=1.1/Z_r.$
Then $0<c_r<1$ and
\begin{equation}\label{eq:entropy-interpolation}
    D_r(\theta)
       \ge-\log\bigl(c_r+(1-c_r)\sqrt{1-\theta^2}\bigr)
       \ge\frac{1-c_r}{2}\theta^2.
\end{equation}

\label{lemma:conditional 2mm}
The following hold as $n$ diverges.
\begin{enumerate}
    \item (Conditional second moment.)
    \begin{equation}\label{eq:conditional 2mm - goal}
        \mathbb{E}_{\unskip\space}\left[Q^2\right]=(1+o(1))\mathbb{E}_{\unskip\space}\left[Q\right]^2,
        \qquad
        \mathbb{E}_{\unskip\space}\left[Q\right]=(1+o(1))\mathbb{E}_{\unskip\space}\left[\mathcal{Z}_I^{\text{\tiny{typ}}}\right].
    \end{equation}

    \item (Log-normal number of solutions.) Let
    \begin{equation}\label{eq:limiting cycle Gaussian}
        W_\alpha\sim\mathcal N\left(
        \frac14\log\bigl(1-4B_{\kappa/r_*,\alpha}^2\bigr),
        -\frac12\log\bigl(1-4B_{\kappa/r_*,\alpha}^2\bigr)
        \right),
    \end{equation}
    where $r_*=r_*(\kappa,\alpha)$. Then
    \begin{equation}\label{eq:conditional 2mm - scaling limit goal}
        \sup_{t\in\mathbb{R}}
        \left|
        \mathbb{P}_{}\left[\mathcal{Z}_I^{\text{\tiny{typ}}}>e^t\mathbb{E}_{\unskip\space}\left[\mathcal{Z}_I^{\text{\tiny{typ}}}\right]\right]
        -\mathbb{P}_{}\left[W_\alpha>t\right]\right|
        =o(1).
    \end{equation}
    In particular,
    \begin{equation}\label{eq:conditional 2mm - tail goal}
        \mathbb{P}_{}\left[
        \frac{\mathcal{Z}_I^{\text{\tiny{typ}}}}{\mathbb{E}_{\unskip\space}\left[\mathcal{Z}_I^{\text{\tiny{typ}}}\right]}
        \notin\bigl((\log n)^{-1/2},(\log n)^{1/2}\bigr)\right]
        =o(1).
    \end{equation}

    \item (Strong freezing.) There is a constant $\delta>0$ such
    that, with high probability,
    \begin{equation}\label{eq:strong freezing conclusion}
        \frac{1}{\mathcal{Z}_I^{\text{\tiny{typ}}}}
        \left|\left\{x\in\mathbf{X}_{n,m,\kappa}^{\text{\tiny{typ}}}:
        (\mathbf{X}_{n,m,\kappa}^{\text{\tiny{typ}}}\setminus\{x\})
        \cap B_{\|\cdot\|_2}(x,\delta\sqrt n)\ne\emptyset\right\}\right|
        \le e^{-n^{.48}}.
    \end{equation}
    Here the left-hand side is defined to be zero when
    $\mathcal{Z}_I^{\text{\tiny{typ}}}=0$.

    \item (Complete freezing.) If, in addition,
    $\alpha_c(\kappa)\in J$ and
    $m=\lfloor\alpha_c(\kappa)n-\eta\log n\rfloor$, then, with
    probability at least $1-n^{-1}$, every
    $x,y\in\mathbf{X}_{n,m,\kappa}^{\text{\tiny{typ}}}$ with $y\notin\{x,-x\}$ satisfy
    \begin{equation}\label{eq:complete freezing conclusion}
        |\langle x,y\rangle|\le\sqrt n\log n.
    \end{equation}
\end{enumerate}

For some $c := c_\kappa > 0$, 
    \begin{equation}\label{eq:conditional first moment}
        \mathbb{E}_{\unskip\space}\left[Q\right] = (1+o(1))\,\mathbb{E}_{\unskip\space}\left[\mathcal{Z}_I^\text{\tiny{typ}}\right] \ge n^{c\eta}.
    \end{equation}

\label{lem:critical first moment}
Under the assumptions and notation of \cref{thm:main2}, for every fixed
$C<\infty$, uniformly over $s$ satisfying
$|s|\le C\log n$ and $m=\alpha_c n+s\in\mathbb N$,
\begin{equation}\label{eq:critical first moment}
    \mathbb{E}_{\unskip\space}\left[\mathcal{Z}(n,m,\kappa)\right]=(C_\kappa+o(1))p_c^s.
\end{equation}

\label{lem:small-window-scalar}
Suppose
\begin{equation}\label{eq:small-window-domain}
    r\ge5,\qquad
    0<K\le2,\qquad
    rK\ge10,\qquad
    \frac{q(r)}{d(K)}
       \ge1+\frac1{r^2K^2}.
\end{equation}
Then
\begin{align}
    Z_r^2(1-q(r)d(K))
       \frac{s_0\log(1/s_0)}{1-s_0}
       &>1.01,\label{eq:small-window-main-scalar}\\
    \frac{4\pi^5}{t^3}\mathcal T_2(u_0)^2
       &<10^{-12}.
       \label{eq:small-window-remainder-bound}
\end{align}

\label{lem:near-binary-entropy}
If $1<r\le1.2$, then
\begin{equation}\label{eq:near-binary-entropy-bound}
    D_r(\theta)\ge\frac{\theta^2}{8},
    \qquad 0\le\theta\le1.
\end{equation}
